try:
    h = (
        spark.table("odw_harmonised_db.sb_application_update")
             .filter(F.col("IsActive") == "Y")
    )

    curated_cols = (
        "details",
        "firstPublished",
        "firstPublishedKey",
        "id",
        "lastEdited",
        "lastEditedKey",
        "status",
        "unpublishedDate",
        "unpublishedDateKey"
    )

    current_cols = set(h.columns)

    # check that all direct-mapped Harmonised columns exist
    direct_cols = [
        "details",
        "firstPublished",
        "id",
        "lastEdited",
        "unpublishedDate"
    ]

    missing = [c for c in direct_cols if c not in current_cols]

    if missing:
        print("Missing in Harmonised:", missing)

    select_exprs = []

    for c in curated_cols:

        if c in current_cols:

            select_exprs.append(F.col(c))

        elif c == "status":

            select_exprs.append(
                F.col("applicationUpdateStatus").alias("status")
            )

        elif c == "firstPublishedKey":

            select_exprs.append(
                F.date_format(
                    F.col("firstPublished"),
                    "yyyyMMdd"
                ).cast("int").alias(c)
            )

        elif c == "lastEditedKey":

            select_exprs.append(
                F.date_format(
                    F.col("lastEdited"),
                    "yyyyMMdd"
                ).cast("int").alias(c)
            )

        elif c == "unpublishedDateKey":

            select_exprs.append(
                F.date_format(
                    F.col("unpublishedDate"),
                    "yyyyMMdd"
                ).cast("int").alias(c)
            )

        else:

            select_exprs.append(
                F.lit(None).alias(c)
            )

    df = h.select(*select_exprs)


except Exception as e:

    error_message = (
        f"Error in SQL query for table "
        f"odw_harmonised_db.application_update : {str(e)[:800]}"
    )

    end_exec_time = datetime.now()
